<template>
 <ElSpace direction="vertical" fill class="v1-page" :size="20"><ElPageHeader title="天枢" content="预测中心" @back="$emit('navigate','overview')"><template #extra><ElSpace><ElSelect v-model="demo" style="width:150px"><ElOption :value="false" label="当前空间" /><ElOption :value="true" label="演示场景" /></ElSelect><ElButton type="primary" :loading="busy" @click="predict">开始预测</ElButton><ElButton type="primary" plain :loading="aiRunning" :disabled="!aiStatus.can_run" @click="previewAI"><ArtSvgIcon icon="ri:sparkling-line" />AI 分析</ElButton></ElSpace></template></ElPageHeader>
  <ElCard v-if="aiResult||aiRunning||aiError" shadow="never"><template #header><ElSpace class="v1-spread"><ElSpace><strong>AI 分析</strong><ElTag v-if="aiResult?.state==='succeeded'" type="success">接口返回</ElTag><ElTag v-if="aiResult?.source==='demo'" type="warning">含模拟数据</ElTag></ElSpace><ElSelect v-if="aiRuns.length" v-model="selectedRun" placeholder="历史分析" style="width:290px" @change="selectRun"><ElOption v-for="r in aiRuns" :key="r.id" :value="r.id" :label="date(r.created)+' · '+({succeeded:'成功',failed:'失败',running:'执行中',unknown:'结果未知'})[r.state]" /></ElSelect></ElSpace></template><ElAlert v-if="aiRunning||aiResult?.state==='running'" title="正在调用已配置的 AI 接口" type="info" show-icon :closable="false" /><ElAlert v-if="aiError" :title="aiError" type="error" show-icon :closable="false" /><template v-if="aiResult"><ElDescriptions :column="3" class="v1-gap"><ElDescriptionsItem label="模型">{{aiResult.model}}</ElDescriptionsItem><ElDescriptionsItem label="数据范围">{{aiResult.days}} 天</ElDescriptionsItem><ElDescriptionsItem label="生成时间">{{date(aiResult.finished)}}</ElDescriptionsItem></ElDescriptions><ElInput v-if="aiResult.state==='succeeded'" :model-value="aiResult.answer" type="textarea" :autosize="{minRows:8,maxRows:24}" readonly /><ElAlert v-else-if="aiResult.error" :title="aiResult.error" type="error" show-icon :closable="false" /></template></ElCard>
  <ElCard shadow="never"><template #header><ElSpace><strong>未来七日 / kWh</strong><ElTag v-if="result" :type="result.source==='demo'?'warning':'info'">{{result.source==='demo'?'演示':'估算'}}</ElTag><ElTooltip v-if="result?.algorithm" :content="result.algorithm"><ElButton text circle aria-label="预测依据"><ArtSvgIcon icon="ri:information-line" /></ElButton></ElTooltip></ElSpace></template><ArtLineChart v-if="result?.available" :data="forecastSeries" :colors="forecastColors" :x-axis-data="result.days.map(d=>d.date.slice(5))" height="300px" :show-legend="true" :smooth="false" /><ElEmpty v-else :description="result?'学习中':'等待预测'" /></ElCard>
  <ElCard v-if="result?.available" shadow="never"><template #header>预测建议</template><ElRow :gutter="20"><ElCol :span="8"><ElStatistic title="未来七日用电" :value="result.suggestions[0].value" :precision="2" suffix="kWh" /></ElCol><ElCol :span="16"><ElDescriptions :column="1"><ElDescriptionsItem label="重点设备"><ElTag v-for="d in ranked.slice(0,3)" :key="d.id" class="v1-tag">{{d.name}}</ElTag></ElDescriptionsItem><ElDescriptionsItem label="建议">{{advice}}</ElDescriptionsItem><ElDescriptionsItem label="样本">{{result.samples}} 个有效日</ElDescriptionsItem></ElDescriptions></ElCol></ElRow></ElCard>
  <ElRow :gutter="20"><ElCol :span="8"><ElCard shadow="never"><ElStatistic title="期间用电" :value="reports?.daily.some(d=>d.kwh!=null)?n(reports.total_kwh,1):'暂无数据'" suffix="kWh" /></ElCard></ElCol><ElCol :span="8"><ElCard shadow="never"><ElStatistic title="期间费用" :value="reports?.daily.some(d=>d.cost!=null)?n(reports.daily.reduce((s,d)=>s+(d.cost||0),0),2):'暂无数据'" prefix="¥" /></ElCard></ElCol><ElCol :span="8"><ElCard shadow="never"><ElStatistic title="有效日" :value="reports?.daily.filter(d=>d.covered_hours>=23.5).length||0" /></ElCard></ElCol></ElRow>
  <ElCard shadow="never"><template #header><ElSpace class="v1-spread"><strong>每日用量 / kWh</strong><ElSpace><ElSelect :model-value="days" style="width:140px" @change="value=>$emit('range',value)"><ElOption v-for="v in [7,14,30,60]" :key="v" :value="v" :label="v+'天'" /></ElSelect><ElButton @click="download">导出</ElButton></ElSpace></ElSpace></template><ArtBarChart v-if="reports" :data="reports.daily.map(d=>d.kwh)" :x-axis-data="reports.daily.map(d=>d.date.slice(5))" height="300px" /></ElCard>
  <ElCard shadow="never"><template #header>设备贡献</template><ArtTable :data="ranked" height="300" :show-table-header="false"><ElTableColumn prop="name" label="设备" /><ElTableColumn prop="area" label="区域" /><ElTableColumn label="用量 / kWh"><template #default="{row}">{{n(row.kwh,2)}}</template></ElTableColumn></ArtTable></ElCard>
 </ElSpace>
 <ElDialog v-model="aiConfirm" title="确认发送 AI 分析数据" width="min(820px,94vw)" :close-on-click-modal="false" align-center><ElScrollbar max-height="64vh"><ElSpace v-if="aiPreview" direction="vertical" fill :size="20" class="v1-dialog-stack"><ElAlert title="将向以下服务发送数据，调用可能产生 API 费用" type="warning" show-icon :closable="false" /><ElDescriptions :column="1" border><ElDescriptionsItem label="接收接口"><ElText class="v1-break">{{aiPreview.endpoint}}</ElText></ElDescriptionsItem><ElDescriptionsItem label="模型">{{aiPreview.model}}</ElDescriptionsItem><ElDescriptionsItem label="数据范围">最近 {{aiPreview.days}} 天 · {{aiPreview.data.scope.included_devices}} 台设备</ElDescriptionsItem><ElDescriptionsItem label="数据来源"><ElTag :type="aiPreview.data.data_source==='demo'?'warning':'info'">{{aiPreview.data.data_source==='demo'?'含模拟数据':'采集数据'}}</ElTag></ElDescriptionsItem><ElDescriptionsItem label="名称">{{aiPreview.data.scope.names_included?'包含空间与设备名称':'匿名设备代号'}}</ElDescriptionsItem></ElDescriptions><ElCollapse><ElCollapseItem title="预设提示词" name="prompt"><ElInput :model-value="aiPreview.prompt" type="textarea" :autosize="{minRows:5,maxRows:10}" readonly /></ElCollapseItem><ElCollapseItem title="将发送的数据包" name="data"><ElInput :model-value="JSON.stringify(aiPreview.data,null,2)" type="textarea" :autosize="{minRows:8,maxRows:14}" readonly /></ElCollapseItem></ElCollapse></ElSpace></ElScrollbar><template #footer><ElButton @click="aiConfirm=false">取消</ElButton><ElButton type="primary" :loading="aiRunning" @click="runAI">确认发送并分析</ElButton></template></ElDialog>
</template>
<script setup>
import {ref,computed,onMounted,onBeforeUnmount} from 'vue';import {ElMessage} from 'element-plus';import {api,n,date} from './api';import {useSettingStore} from './art/store/modules/setting';const chartTheme=useSettingStore();const forecastColors=computed(()=>[chartTheme.systemThemeColor,'#4ABEFF','#14DEBA']);
const props=defineProps({spaceId:String,reports:Object,days:Number});const emit=defineEmits(['range','navigate']);const demo=ref(false),busy=ref(false),result=ref(null);const ranked=computed(()=>props.reports?.ranking||[]);const advice=computed(()=>ranked.value.length?'优先核查 '+ranked.value.slice(0,3).map(d=>d.name).join('、')+' 的运行时段，比较营业时段与非营业时段的用量。':'演示场景建议核查空调、照明和待机负荷；安排可转移设备错峰运行。');
const forecastSeries=computed(()=>[{name:'预计用量',data:result.value?.days.map(d=>d.kwh)||[]},{name:'参考上界',data:result.value?.days.map(d=>d.high)||[]},{name:'参考下界',data:result.value?.days.map(d=>d.low)||[]}]);
async function predict(){busy.value=true;try{result.value=await api('prediction?space_id='+props.spaceId+'&demo='+(demo.value?'1':'0'))}catch(e){ElMessage.error(e.message)}finally{busy.value=false}}
function download(){location.href='/api/export?space_id='+props.spaceId+'&days='+props.days}

const aiStatus=ref({can_run:false}),aiRuns=ref([]),selectedRun=ref(''),aiResult=ref(null),aiPreview=ref(null),aiConfirm=ref(false),aiRunning=ref(false),aiError=ref('');
async function loadAI(){try{const [s,h]=await Promise.all([api('ai-status?space_id='+props.spaceId),api('ai-history?space_id='+props.spaceId)]);aiStatus.value=s;aiRuns.value=h.runs;if(!aiRunning.value&&h.runs.length){const chosen=h.runs.find(r=>r.id===selectedRun.value)||h.runs[0];aiResult.value=chosen;selectedRun.value=chosen.id}}catch(e){aiError.value=e.message}}
function selectRun(id){aiResult.value=aiRuns.value.find(r=>r.id===id)||null;aiError.value=''}
async function previewAI(){if(!aiStatus.value.configured||!aiStatus.value.enabled){ElMessage.warning('请在后端设置中配置并启用 AI 分析');emit('navigate','settings');return}try{aiPreview.value=await api('ai-preview',{space_id:props.spaceId});aiConfirm.value=true}catch(e){ElMessage.error(e.message)}}
async function runAI(){if(aiRunning.value)return;aiRunning.value=true;aiError.value='';aiConfirm.value=false;aiResult.value=null;try{aiResult.value=await api('ai-analyze',{token:aiPreview.value.token,confirm_send:true});selectedRun.value=aiResult.value.id;await loadAI();ElMessage.success('AI 分析完成')}catch(e){aiError.value=e.message;await loadAI()}finally{aiRunning.value=false}}
let historyPoll;onMounted(()=>{loadAI();historyPoll=setInterval(()=>{if(!aiRunning.value&&aiRuns.value.some(r=>r.state==='running'))loadAI()},3000)});onBeforeUnmount(()=>clearInterval(historyPoll));
</script>
